      const q = rel+'/'+ent.name;
      if (ent.isSymbolicLink()) throw Error('Symlink in scoped physical tree: '+q);
      if (ent.isDirectory()) { directories.push(q.slice(p.length+1)); visit(q); }
      else if (ent.isFile()) files.push(q.slice(p.length+1));
